#include <cstdint>
#include <iostream>
#include <tuple>
#include <vector>

// ts_ns, symbol, qty, price_ticks
using Fill = std::tuple<std::int64_t, const char*, int, std::int64_t>;

template <typename First, typename... Rest>
void log_line(const First& first, const Rest&... rest) {
    std::cout << first;
    ((std::cout << ' ' << rest), ...);
    std::cout << '\n';
}

std::int64_t notional(std::int64_t, const char*, int qty, std::int64_t price_ticks) {
    return qty * price_ticks;
}

int main() {
    std::vector<Fill> fills;
    fills.reserve(3);
    // Hot path: store the raw fields, format nothing.
    fills.emplace_back(34200000000150, "AAPL", 100, 19275);
    fills.emplace_back(34200000000420, "MSFT", 50, 41010);
    fills.emplace_back(34200000000777, "AAPL", -40, 19280);

    std::cout << std::tuple_size_v<Fill> << " fields, " << sizeof(Fill) << " bytes\n";
    // Cold path: unpack each record into a call.
    std::int64_t total = 0;
    for (const Fill& fill : fills) {
        std::apply([](const auto&... fields) { log_line(fields...); }, fill);
        total += std::apply(notional, fill);
    }
    std::cout << "notional " << total << '\n';
    return 0;
}

