#include <cstdint>
#include <iostream>
#include <string>

struct AddOrder {
    static constexpr char tag = 'A';
    std::int64_t id = 0;
    std::int64_t price_ticks = 0;
    std::int64_t qty = 0;
    static AddOrder read(std::istream& in) { AddOrder m; in >> m.id >> m.price_ticks >> m.qty; return m; }
};

struct Cancel {
    static constexpr char tag = 'X';
    std::int64_t id = 0;
    static Cancel read(std::istream& in) { Cancel m; in >> m.id; return m; }
};

struct Trade {
    static constexpr char tag = 'T';
    std::int64_t price_ticks = 0;
    std::int64_t qty = 0;
    static Trade read(std::istream& in) { Trade m; in >> m.price_ticks >> m.qty; return m; }
};

struct FeedCounts {
    int adds = 0;
    int cancels = 0;
    std::int64_t volume = 0;
    void on(const AddOrder&) { ++adds; }
    void on(const Cancel&) { ++cancels; }
    void on(const Trade& t) { volume += t.qty; }
};

template <typename... Msgs, typename Handler>
bool dispatch(char tag, std::istream& in, Handler& handler) {
    return ((tag == Msgs::tag && (handler.on(Msgs::read(in)), true)) || ...);
}

int main() {
    FeedCounts counts;
    int unknown = 0;
    char tag = 0;
    while (std::cin >> tag) {
        if (!dispatch<AddOrder, Cancel, Trade>(tag, std::cin, counts)) {
            ++unknown;
            std::string rest;
            std::getline(std::cin, rest);  // skip a message we can't read
        }
    }
    std::cout << "adds " << counts.adds << ", cancels " << counts.cancels << ", volume " << counts.volume
              << ", unknown " << unknown << '\n';
    return 0;
}

